    fun translate(key: String, langCode: String, fallback: String = key): String {
        if (langCode == "en") return fallback.ifBlank { key }
        val dict = translations[key]
        if (dict != null) {
            val regional = dict[langCode]
            if (!regional.isNullOrBlank()) return regional
            val hindiFallback = dict["hi"]
            if (!hindiFallback.isNullOrBlank()) return hindiFallback
        }
        return fallback.ifBlank { key }
    }

    fun getLanguageName(code: String): String {
        val lang = SUPPORTED_LANGUAGES.find { it.code == code }
        return if (lang != null) "${lang.nativeName} (${lang.englishName})" else "English"
    }

    fun getCurrentLanguage(context: android.content.Context): String {
        val prefs = context.getSharedPreferences("dhaaga_session", android.content.Context.MODE_PRIVATE)
        return prefs.getString("selected_language", "en") ?: "en"
    }

    fun getStudioLoadingSteps(langCode: String): List<String> {
        return listOf(
            translate("studio_stage_lighting", langCode, "Fixing studio lights & softbox daylight..."),
            translate("studio_stage_glare", langCode, "Eliminating camera flash glare & reflections..."),
            translate("studio_stage_backdrop", langCode, "Staging pure catalog backdrop & table..."),
            translate("studio_stage_shadow", langCode, "Positioning realistic soft drop shadows..."),
            translate("studio_stage_texture", langCode, "Polishing handcrafted textures & micro-details..."),
            translate("studio_stage_rendering", langCode, "Rendering high-res commercial catalog photo..."),
            translate("studio_stage_finalizing", langCode, "Applying final studio touches...")
        )
    }
